// budgeted: fetch the prompt, capture the frame, then ask the model.
const VERDICT_WINDOW_MS = 3000;
const MODEL_PROMPT_TIMEOUT_MS = 300;
const CAPTURE_TIMEOUT_MS = 900;
const MODEL_TIMEOUT_MS = 1500;
